parameters.jsCode:
const results = $json.results.slice(0, 3).map(r => ({
  title: r.title,
  url: r.url,
  snippet: r.content.slice(0, 300)
}));
return { json: { ...$('Split Out').item.json, tavily: results } };

// Parse Claude response
const text = $json.content[0].text;
const parsed = JSON.parse(text);

// Split reasoning into two parts
const reasoning1 = parsed.reasoning.headline;
const reasoning2 = parsed.reasoning.detail;

// NewsAPI fields from upstream node
const newsItem = $('Split Out').item.json;

const payload = {
  title:             newsItem.title,
  source:            newsItem.source.name,
  imageUrl:          newsItem.urlToImage || '',
  url:               newsItem.url,
  verdict:           parsed.verdict,
  score:             parsed.score,
  summary:           parsed.summary,
  reasoning1,
  reasoning2,
  finding:           parsed.conclusion,
  flags:             parsed.red_flags || [],
  supportingSources: (parsed.supporting_sources || []).filter(s => s.name && s.url),
  opposingSources: (parsed.opposing_sources || []).filter(s => s.name && s.url),
  caption: `${parsed.summary}\n\nVerdict: ${parsed.verdict} (${parsed.score}/10)\n\nSource: ${newsItem.url}\n\n${parsed.supporting_sources.map(s => `✅ ${s.name}: ${s.article_url}`).join('\n')}\n${parsed.opposing_sources.map(s => `❌ ${s.name}: ${s.article_url}`).join('\n')}\n\n#FactCheck #MediaLiteracy #BreakingNews`,
  recommended_action: parsed.recommended_action,
};

// Call renderer (internal docker network address)
const rendererResponse = await helpers.httpRequest({
  method: 'POST',
  url: 'http://renderer:3500/render',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(payload),
});

if (!rendererResponse.success) {
  throw new Error('Renderer failed: ' + (rendererResponse.error || JSON.stringify(rendererResponse)));
}

// Renderer returns relative paths like /images/<batch>_slide1.jpg
const imageUrls = rendererResponse.images;

return {
  ...payload,
  slideUrls: imageUrls,
  slide1: imageUrls[0],
  slide2: imageUrls[1],
  slide3: imageUrls[2],
  slide4: imageUrls[3],
  slide5: imageUrls[4],
  slide6: imageUrls[5],
  slide7: imageUrls[6],
  batchId: rendererResponse.batchId,
};

