const IG_USER_ID = $env.META_INSTAGRAM_ACCOUNT_ID;
const ACCESS_TOKEN = $env.META_ACCESS_TOKEN;
const DOMAIN = $env.DOMAIN_NAME;

const containerIds = [];

for (const slidePath of $json.slideUrls) {
  // Renderer returns relative paths (/images/...). Instagram needs a public URL,
  // so the domain is prefixed only here.
  const imageUrl = `https://${DOMAIN}${slidePath}`;

  const res = await helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v19.0/${IG_USER_ID}/media`,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      image_url: imageUrl,
      is_carousel_item: true,
      access_token: ACCESS_TOKEN,
    }),
  });

  if (!res.id) {
    throw new Error(`Container failed for: ${imageUrl} — ${JSON.stringify(res)}`);
  }

  containerIds.push(res.id);
}

return [{ json: { ...$json, carouselContainerIds: containerIds.join(',') } }];
